package com.mushafi.app;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.AudioAttributes;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import org.json.*;
import java.util.*;

/** Native one-shot alarms, rebuilt after each event, reboot and clock/time-zone changes. */
public final class PrayerScheduler {
 public static final String ACTION="com.mushafi.app.PRAYER_EVENT";
 static final int REQUEST=7031;
 public static class Event{public long at;public String key,kind,id;Event(long t,String k,String type){at=t;key=k;kind=type;id=t+"|"+k+"|"+type;}}
 static AlarmManager alarms(Context c){return(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);}
 public static boolean exact(Context c){return Build.VERSION.SDK_INT<31||alarms(c).canScheduleExactAlarms();}
 public static boolean notifications(Context c){if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return false;return Build.VERSION.SDK_INT<24||((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled();}
 static PendingIntent pending(Context c,Event e){Intent intent=new Intent(c,PrayerAlarmReceiver.class).setAction(ACTION);if(e!=null)intent.putExtra("at",e.at).putExtra("key",e.key).putExtra("kind",e.kind).putExtra("id",e.id);return PendingIntent.getBroadcast(c,REQUEST,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static List<Event> events(PrayerSettings s,long now)throws JSONException{
  List<Event> result=new ArrayList<>(),onsets=new ArrayList<>();
  for(int d=-1;d<=2;d++){JSONObject day=PrayerCalculator.calculate(s,PrayerCalculator.day(s,now,d));for(String key:PrayerSettings.KEYS)onsets.add(new Event(day.getLong(key),key,"adhan"));}
  Collections.sort(onsets,(a,b)->Long.compare(a.at,b.at));
  for(int i=0;i<onsets.size();i++){Event onset=onsets.get(i);JSONObject row=s.row(onset.key);long iqama=onset.at+row.optInt("iqama")*PrayerCalculator.MINUTE,next=i+1<onsets.size()?onsets.get(i+1).at:Long.MAX_VALUE;
   if(row.optBoolean("adhan"))result.add(onset);
   // An iqama setting that overlaps the next prayer must not generate a misleading alert.
   if(iqama>=next)continue;
   if(row.optBoolean("reminder")&&row.optInt("iqama")>s.json.optInt("reminderMinutes"))result.add(new Event(iqama-s.json.optInt("reminderMinutes")*PrayerCalculator.MINUTE,onset.key,"reminder"));
   if(row.optBoolean("atIqama")&&row.optInt("iqama")>0)result.add(new Event(iqama,onset.key,"iqama"));
  }
  Calendar refresh=PrayerCalculator.day(s,now,1);refresh.set(Calendar.HOUR_OF_DAY,0);refresh.set(Calendar.MINUTE,2);refresh.set(Calendar.SECOND,0);refresh.set(Calendar.MILLISECOND,0);result.add(new Event(refresh.getTimeInMillis(),"day","refresh"));Collections.sort(result,(a,b)->Long.compare(a.at,b.at));return result;
 }
 public static synchronized void schedule(Context c){DailyReminderScheduler.schedule(c);KhatmaScheduler.schedule(c);PrayerSettings s=PrayerSettings.load(c);PrayerRemoteSource.refresh(c,s,null);android.content.SharedPreferences prefs=c.getSharedPreferences("prayer_times",0);try{String previousNext=prefs.getString("next","");alarms(c).cancel(pending(c,null));prefs.edit().remove("next").remove("error").apply();if(!s.enabled()||!notifications(c)){cancelPrayerNotifications(c);return;}AdhanPlaybackService.reconcile(c);if(!exact(c))return;
   channels(c,s);long now=System.currentTimeMillis();if(!previousNext.isEmpty()){JSONObject previous=new JSONObject(previousNext);long at=previous.optLong("at");if(at<=now&&now-at<=120000){String key=previous.optString("key"),kind=previous.optString("kind");deliver(c,new Intent(ACTION).putExtra("at",at).putExtra("key",key).putExtra("kind",kind).putExtra("id",at+"|"+key+"|"+kind));}}Set<String> delivered=prefs.getStringSet("delivered",Collections.emptySet());for(Event e:events(s,now)){if(e.at<=now||delivered.contains(e.id)||(!e.kind.equals("refresh")&&!channelEnabled(c,notificationChannel(c,s,e.kind))))continue;if(e.kind.equals("refresh"))alarms(c).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,e.at,pending(c,e));else alarms(c).setAlarmClock(new AlarmManager.AlarmClockInfo(e.at,PendingIntent.getActivity(c,7033,new Intent(c,MainActivity.class).putExtra("openPrayer",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)),pending(c,e));prefs.edit().putString("next",new JSONObject().put("at",e.at).put("key",e.key).put("kind",e.kind).toString()).apply();break;}
  }catch(Exception e){prefs.edit().putString("error","تعذر حساب المواقيت أو جدولة التنبيه؛ راجع الموقع وصلاحية التنبيه الدقيق").apply();}
 }
 public static boolean channelEnabled(Context c,String id){if(Build.VERSION.SDK_INT<26)return true;NotificationChannel channel=((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getNotificationChannel(id);return channel!=null&&channel.getImportance()!=NotificationManager.IMPORTANCE_NONE;}
 public static void cancelPrayerNotifications(Context c){AdhanPlaybackService.cancel(c);NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);for(String key:PrayerSettings.KEYS)for(String kind:new String[]{"adhan","reminder","iqama"})manager.cancel(Math.abs((key+kind).hashCode()));manager.cancel(7099);manager.cancel(AdhanPlaybackService.NOTICE);}
 static String channel(PrayerSettings s,String kind){return kind.equals("adhan")?"prayer_adhan_"+s.json.optString("voice")+"_v1":"prayer_iqama_v1";}
 public static void channels(Context c,PrayerSettings s){if(Build.VERSION.SDK_INT<26)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String[] labels={"مشاري العفاسي","أحمد النفيس","منصور الزهراني","مصطفى أوزجان","صامت"};for(int i=0;i<PrayerSettings.VOICES.length;i++){String voice=PrayerSettings.VOICES[i];NotificationChannel ch=new NotificationChannel("prayer_adhan_"+voice+"_v1",UiLocale.text(c,"الأذان المختصر")+" · "+UiLocale.text(c,labels[i]),NotificationManager.IMPORTANCE_HIGH);ch.setDescription(UiLocale.text(c,"تكبيرات قصيرة عند دخول وقت الصلاة؛ يمكن التحكم بالصوت من إعدادات النظام"));ch.setSound(voice.equals("silent")?null:Uri.parse("android.resource://"+c.getPackageName()+"/raw/adhan_"+voice),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION_EVENT).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());ch.enableVibration(!voice.equals("silent"));nm.createNotificationChannel(ch);}
  NotificationChannel alarm=new NotificationChannel(AdhanPlaybackService.CHANNEL,UiLocale.text(c,"الأذان بصوت المنبّه"),NotificationManager.IMPORTANCE_HIGH);alarm.setDescription(UiLocale.text(c,"إشعار تشغيل الأذان؛ مستوى الصوت من المنبّهات داخل إعدادات الصوت"));alarm.setSound(null,null);alarm.enableVibration(false);nm.createNotificationChannel(alarm);
  NotificationChannel iq=new NotificationChannel("prayer_iqama_v1",UiLocale.text(c,"تذكير الإقامة"),NotificationManager.IMPORTANCE_HIGH);iq.setDescription(UiLocale.text(c,"قبل الإقامة وعند حلول موعدها الشخصي"));iq.enableVibration(true);nm.createNotificationChannel(iq);
 }
 public static String notificationChannel(Context c,PrayerSettings s,String kind){return kind.equals("adhan")&&AdhanPlaybackService.enabled(c)?AdhanPlaybackService.CHANNEL:channel(s,kind);}
 static String prayerName(String key){for(int i=0;i<PrayerSettings.KEYS.length;i++)if(PrayerSettings.KEYS[i].equals(key))return PrayerSettings.NAMES[i];return "الصلاة";}
 public static synchronized void deliver(Context c,Intent intent){PrayerSettings s=PrayerSettings.load(c);if(!s.enabled()||!notifications(c))return;long now=System.currentTimeMillis(),at=intent.getLongExtra("at",0);if(at>now+2000||now-at>120000)return;String id=intent.getStringExtra("id"),kind=intent.getStringExtra("kind"),key=intent.getStringExtra("key");if("refresh".equals(kind))return;try{boolean valid=false;for(Event e:events(s,now))if(e.id.equals(id)){valid=true;break;}if(!valid||("reminder".equals(kind)&&now>=at+s.json.optInt("reminderMinutes")*PrayerCalculator.MINUTE))return;if("adhan".equals(kind)&&PrayerMute.muted(c,key,at)){JSONObject quiet=new JSONObject(s.json.toString());quiet.put("voice","silent");s=new PrayerSettings(quiet);}android.content.SharedPreferences prefs=c.getSharedPreferences("prayer_times",0);Set<String> delivered=new HashSet<>(prefs.getStringSet("delivered",Collections.emptySet()));if(delivered.contains(id))return;for(Iterator<String> iterator=delivered.iterator();iterator.hasNext();){String value=iterator.next();try{if(now-Long.parseLong(value.split("\\|")[0])>7*86400000L)iterator.remove();}catch(Exception e){iterator.remove();}}if(!channelEnabled(c,notificationChannel(c,s,kind)))return;notifyEvent(c,s,key,kind,at,false);delivered.add(id);prefs.edit().putStringSet("delivered",delivered).commit();}catch(Exception ignored){}
 }
 private static String minutes(int number){String value=String.valueOf(number);for(int i=0;i<10;i++)value=value.replace((char)('0'+i),(char)('٠'+i));return value+(number>=3&&number<=10?" دقائق":" دقيقة");}
 public static void notifyEvent(Context c,PrayerSettings s,String key,String kind,long at,boolean test){channels(c,s);boolean alarm=kind.equals("adhan")&&AdhanPlaybackService.enabled(c);if(kind.equals("adhan")&&!s.json.optString("voice").equals("silent")&&AdhanPlaybackService.allowed(c,s)&&AdhanPlaybackService.audible(c)){try{Intent play=new Intent(c,AdhanPlaybackService.class).putExtra("key",key).putExtra("at",at).putExtra("test",test);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(play);else c.startService(play);return;}catch(Exception e){alarm=false;AdhanPlaybackService.state(c,"error","تعذر تشغيل الأذان في الخلفية؛ استُخدم إشعار النظام وفق إعدادات الصوت. راجع قيود البطارية وأعد التجربة.");}}if(kind.equals("adhan")&&!alarm&&!AdhanPlaybackService.audible(c))AdhanPlaybackService.state(c,"stopped","الهاتف صامت أو صوت التنبيهات مكتوم؛ استُخدم إشعار النظام.");((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(test?7099:Math.abs((key+kind).hashCode()),notification(c,s,key,kind,at,test,alarm,false));}
 public static Notification notification(Context c,PrayerSettings s,String key,String kind,long at,boolean test,boolean alarm,boolean ongoing){return notification(c,s,key,kind,at,test,alarm,ongoing,ongoing);}
 public static Notification notification(Context c,PrayerSettings s,String key,String kind,long at,boolean test,boolean alarm,boolean ongoing,boolean muteSystemAlert){channels(c,s);String name=UiLocale.text(c,prayerName(key)),title,body;if(kind.equals("adhan")){title=UiLocale.text(c,"حان وقت صلاة {0}",name);int remaining=(int)Math.max(0,Math.ceil((at+s.row(key).optInt("iqama")*PrayerCalculator.MINUTE-System.currentTimeMillis())/(double)PrayerCalculator.MINUTE));body=remaining>0?UiLocale.text(c,"الإقامة بعد {0}",UiLocale.text(c,"{0} دقيقة",UiLocale.number(c,remaining))):UiLocale.text(c,"حيّ على الصلاة");}else if(kind.equals("reminder")){int remaining=(int)Math.max(0,Math.ceil((at+s.json.optInt("reminderMinutes")*PrayerCalculator.MINUTE-System.currentTimeMillis())/(double)PrayerCalculator.MINUTE));title=remaining>0?UiLocale.text(c,"اقتربت إقامة صلاة {0}",name):UiLocale.text(c,"موعد إقامة صلاة {0}",name);body=remaining>0?UiLocale.text(c,"متبقي {0} على إقامة صلاة {1}",UiLocale.text(c,"{0} دقيقة",UiLocale.number(c,remaining)),name):UiLocale.text(c,"حان وقت إقامة صلاة {0}",name);}else{title=UiLocale.text(c,"موعد إقامة صلاة {0}",name);body=UiLocale.text(c,"حان وقت إقامة صلاة {0}",name);}if(test){title=UiLocale.text(c,"تجربة تنبيه الصلاة");body=UiLocale.text(c,"تنبيه تجريبي، وليس دخول وقت الصلاة");}
  Intent open=new Intent(c,MainActivity.class).putExtra("openPrayer",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,7032,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,alarm?AdhanPlaybackService.CHANNEL:channel(s,kind)):new Notification.Builder(c);AppIdentity.decorate(c,builder).setContentTitle(title).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(pi).setAutoCancel(!ongoing).setOngoing(ongoing).setCategory(alarm?Notification.CATEGORY_ALARM:Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PUBLIC).setWhen(at).setShowWhen(true).setColor(AppIdentity.notificationColor(c)).setOnlyAlertOnce(true);
  if(kind.equals("adhan")&&muteSystemAlert&&Build.VERSION.SDK_INT>=26){builder.setGroup("mushafi_adhan_audio").setGroupAlertBehavior(Notification.GROUP_ALERT_SUMMARY);}
  if(ongoing){PendingIntent stop=PendingIntent.getBroadcast(c,7911,new Intent(c,AdhanStopReceiver.class).setAction(AdhanPlaybackService.STOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);builder.addAction(android.R.drawable.ic_media_pause,UiLocale.text(c,"إيقاف الأذان"),stop);}
  if(Build.VERSION.SDK_INT>=26){if(!ongoing)builder.setTimeoutAfter(5*60000L);}else{builder.setPriority(Notification.PRIORITY_HIGH);if(kind.equals("adhan")){if(!ongoing&&!alarm&&!s.json.optString("voice").equals("silent"))builder.setSound(Uri.parse("android.resource://"+c.getPackageName()+"/raw/adhan_"+s.json.optString("voice")));}else builder.setDefaults(Notification.DEFAULT_SOUND|Notification.DEFAULT_VIBRATE);}
  return builder.build();
 }
 public static JSONObject status(Context c)throws JSONException{PrayerSettings s=PrayerSettings.load(c);channels(c,s);JSONObject j=new JSONObject();android.media.AudioManager audio=(android.media.AudioManager)c.getSystemService(Context.AUDIO_SERVICE);boolean alarm=AdhanPlaybackService.enabled(c);j.put("adhanOnSilent",alarm);j.put("alarmVolume",audio.getStreamVolume(android.media.AudioManager.STREAM_ALARM));j.put("alarmMax",audio.getStreamMaxVolume(android.media.AudioManager.STREAM_ALARM));j.put("adhanAudioError",c.getSharedPreferences("prayer_audio",0).getString("error",""));j.put("notifications",notifications(c));j.put("exact",exact(c));j.put("enabled",s.enabled());j.put("batteryRestricted",Build.VERSION.SDK_INT>=28&&((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).isBackgroundRestricted());String next=c.getSharedPreferences("prayer_times",0).getString("next","");j.put("next",next.isEmpty()?JSONObject.NULL:new JSONObject(next));j.put("error",c.getSharedPreferences("prayer_times",0).getString("error",""));
  if(Build.VERSION.SDK_INT>=26){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel ch=nm.getNotificationChannel(notificationChannel(c,s,"adhan")),iq=nm.getNotificationChannel("prayer_iqama_v1");j.put("adhanChannel",ch!=null&&ch.getImportance()!=NotificationManager.IMPORTANCE_NONE);j.put("adhanSound",alarm?!s.json.optString("voice").equals("silent")&&audio.getStreamVolume(android.media.AudioManager.STREAM_ALARM)>0:ch!=null&&ch.getImportance()>=NotificationManager.IMPORTANCE_DEFAULT&&ch.getSound()!=null);j.put("iqamaChannel",iq!=null&&iq.getImportance()!=NotificationManager.IMPORTANCE_NONE);JSONObject voices=new JSONObject();for(String voice:PrayerSettings.VOICES){NotificationChannel v=nm.getNotificationChannel(alarm?AdhanPlaybackService.CHANNEL:"prayer_adhan_"+voice+"_v1");voices.put(voice,new JSONObject().put("enabled",v!=null&&v.getImportance()!=NotificationManager.IMPORTANCE_NONE).put("sound",alarm?!voice.equals("silent")&&audio.getStreamVolume(android.media.AudioManager.STREAM_ALARM)>0:v!=null&&v.getImportance()>=NotificationManager.IMPORTANCE_DEFAULT&&v.getSound()!=null));}j.put("voices",voices);}return j;
 }
}
